insert into public.content_exercises (id, grp, name, muscle, equip, simple, tip, note, lift, unit, sort) values
  ('ARC-078', 'Cuádriceps', 'Sentadilla búlgara con mancuernas', 'Cuádriceps, glúteo', 'Mancuernas + banco', 'Con el empeine de atrás apoyado en un banco y una mancuerna en cada mano, bajas en vertical doblando la rodilla de delante y subes empujando con ese pie.', 'Inclinar un poco el tronco hacia delante carga más el glúteo; más recta, más cuádriceps. Empieza con poco peso hasta pillar el equilibrio.', '', '', '', 78),
  ('ARC-079', 'Abdomen', 'Rueda abdominal', 'Recto abdominal, core', 'Rueda', 'De rodillas con la rueda en las manos, la llevas hacia delante estirando el cuerpo y vuelves tirando con el abdomen.', 'Aprieta glúteo y no dejes que se hunda la zona lumbar. Llega solo hasta donde puedas volver sin arquear la espalda.', '', '', '', 79),
  ('ARC-080', 'Cuádriceps', 'Sentadilla con peso corporal', 'Cuádriceps, glúteo', 'Peso corporal', 'Con los pies a la anchura de los hombros y los brazos delante, bajas llevando la cadera atrás y abajo y vuelves a subir.', 'Ideal para aprender el movimiento o calentar. Rodillas en la línea de las puntas y talones pegados al suelo.', '', '', '', 80),
  ('ARC-081', 'Abdomen', 'Crunch en el suelo', 'Recto abdominal', 'Peso corporal', 'Tumbada bocarriba con las rodillas dobladas, despegas los hombros del suelo curvando la espalda alta y bajas despacio.', 'No tires del cuello: la barbilla un poco separada del pecho. Sube solo hasta despegar los omóplatos, el resto lo hacen los flexores de cadera.', '', '', '', 81)
